  es_sv(mA, MA, nA, ca, cb, nB, r, A, B) { return `Moles de ${A}: n = ${mA} / ${MA} = ${nA} mol. Proporción: ${this.es_f(nA, ca, cb, A, B)} = ${nB} mol de ${B}. En condiciones normales, cada mol de gas ocupa 22,4 L: V = ${nB} · 22,4 = <b>${r} L</b>`; },
