  es_sl: (mA, MA, nA, mB, MB, nB, ca, cb, qA, qB, A, B, L) => `Moles: ${A}, ${mA} / ${MA} = ${nA} mol; ${B}, ${mB} / ${MB} = ${nB} mol. Cocientes moles / coeficiente: ${A}, ${nA} / ${ca} = ${qA}; ${B}, ${nB} / ${cb} = ${qB}. El menor es el del ${L}: el <b>${L}</b> es el limitante (se acaba antes; del otro sobra una parte).`,
