  es_qd: (eq, m, A, c) => `${eq}<br>¿Cuántos mL de HCl de concentración ${c} mol/L hacen falta para que reaccionen ${m} g de ${A}?`,
  es_sd: (m, M, n, ch, nH, c, V, mL, A) => `Moles de ${A}: n = ${m} / ${M} = ${n} mol. Proporción: ${n} mol ${A} · (${ch} mol HCl / 1 mol ${A}) = ${nH} mol de HCl. Sustituimos en n = c · V: ${nH} = ${c} · V, así que V = ${nH} / ${c} = ${V} L = <b>${mL} mL</b>`,
  es_qr: (eq, mA, A, obt, P) => `${eq}<br>A partir de ${mA} g de ${A} se obtienen ${obt} g de ${P}. ¿Cuál es el rendimiento (%)?`,
  es_sr(mA, MA, nA, ca, cp, nP, MP, teo, obt, y, A, P) { return `Cantidad teórica: ${mA} / ${MA} = ${nA} mol de ${A}; ${this.es_f(nA, ca, cp, A, P)} = ${nP} mol de ${P}, es decir, ${nP} · ${MP} = ${teo} g. Rendimiento = obtenida / teórica · 100 = ${obt} / ${teo} · 100 = <b>${y} %</b>`; },
  er_q: [(dh) => `Una reacción tiene ΔH = ${dh} kJ. ¿Es exotérmica o endotérmica?`,
    (r0, mx, p, w) => `En un diagrama de energía, los reactivos están a ${r0} kJ, la cumbre a ${mx} kJ y los productos a ${p} kJ. ¿Cuánto vale ${["la energía de activación de la reacción directa", "la energía de activación de la reacción inversa", "ΔH, con su signo,"][w]} en kJ?`,
    (nm, f, m, M, dh) => `La combustión del ${nm} (${f}, M = ${M} g/mol) tiene ΔH = −${dh} kJ por cada mol. ¿Cuántos kJ desprende la combustión de ${m} g?`,
    (c1, c2, dt) => `En la reacción A → B, la concentración de A baja de ${c1} a ${c2} mol/L en ${dt} s. ¿Cuál es la velocidad media (mol/(L·s))?`],
  er_o: ["Exotérmica (desprende calor)", "Endotérmica (absorbe calor)"],
  er_s: [(dh, k) => `ΔH = ${dh} kJ ${k === 0 ? "< 0" : "> 0"}: <b>${k === 0 ? "exotérmica" : "endotérmica"}</b>.`,
    (r0, mx, p, w, r) => [`La directa sube desde los reactivos hasta la cumbre: E<sub>a</sub> = ${mx} − ${r0.startsWith("−") ? "(" + r0 + ")" : r0} = <b>${r} kJ</b>.`,
      `La inversa parte de los productos y sube a la misma cumbre: E<sub>a</sub> = ${mx} − ${p.startsWith("−") ? "(" + p + ")" : p} = <b>${r} kJ</b>.`,
      `ΔH = productos − reactivos = ${p} − ${r0.startsWith("−") ? "(" + r0 + ")" : r0} = <b>${r} kJ</b> (${r.startsWith("−") ? "negativo: exotérmica" : "positivo: endotérmica"}).`][w],
    (m, M, n, dh, r) => `Moles: n = ${m} / ${M} = ${n} mol. Cada mol desprende ${dh} kJ (el signo menos de ΔH dice que la reacción pierde esa energía): Q = ${n} · ${dh} = <b>${r} kJ</b> desprendidos.`,
    (c1, c2, dt, dc, r) => `v = −Δ[A] / Δt = −(${c2} − ${c1}) / ${dt} = −(${dc}) / ${dt} = <b>${r} mol/(L·s)</b> (el signo menos hace que salga positiva, porque A disminuye).`],
  ph_q: [e => `¿Qué pH tiene una disolución con [H⁺] = 10<sup>−${e}</sup> mol/L?`, (a, b) => `¿Cuántas veces más ácida es una disolución de pH ${a} que una de pH ${b}?`,
    p => `Una disolución tiene pH ${p}. ¿Es ácida, neutra o básica?`,
    (ac, c) => `¿Qué pH tiene una disolución de ${ac} de concentración ${c} mol/L? (Es un ácido fuerte.)`,
    (cb, Va, ac, ca) => `¿Cuántos mL de NaOH de concentración ${cb} mol/L hacen falta para neutralizar ${Va} mL de ${ac} de concentración ${ca} mol/L?`,
    (Va, ac, Vb, cb) => `${Va} mL de ${ac} de concentración desconocida necesitan ${Vb} mL de NaOH de concentración ${cb} mol/L para neutralizarse. ¿Qué concentración tiene el ácido (mol/L)?`],
  ph_s: [(e) => `pH = −log 10<sup>−${e}</sup> = <b>${e}</b>`, (a, b, r) => `Cada unidad es un factor 10: 10<sup>${b - a}</sup> = <b>${r}</b> veces.`, (p, k) => `pH ${p}: <b>${["ácida", "neutra", "básica"][k]}</b> (7 es neutro).`,
    (ac, c, e) => `El ${ac} es fuerte y se disocia por completo: [H⁺] = ${c} = 10<sup>−${e}</sup> mol/L, así que pH = <b>${e}</b>.`,
    (ca, Va, na, ac, k, nb, cb, VbL, Vb) => `Moles de ácido: n = c · V = ${ca} · ${Va} = ${na} mol. ` + (k === 1 ? `Proporción 1 : 1 (HCl + NaOH → NaCl + H₂O): ${nb} mol de NaOH. ` : `Proporción 1 : 2 (H₂SO₄ + 2 NaOH → Na₂SO₄ + 2 H₂O): ${na} · 2 = ${nb} mol de NaOH. `) + `Volumen: V = n / c = ${nb} / ${cb} = ${VbL} L = <b>${Vb} mL</b>`,
    (cb, VbL, nb, ac, k, na, Va, ca) => `Moles de NaOH: n = ${cb} · ${VbL} = ${nb} mol. ` + (k === 1 ? `Proporción 1 : 1: también hay ${na} mol de HCl. ` : `Proporción 1 : 2: hay la mitad de H₂SO₄, ${nb} / 2 = ${na} mol. `) + `Concentración: c = ${na} / ${Va} = <b>${ca} mol/L</b>`],
  ph_o: ["Ácida", "Neutra", "Básica"],
  di_dim: { q: (x, df) => `¿Cuáles son las dimensiones ${x.startsWith("el ") ? "del " + x.slice(3) : "de " + x} (${df})?`, sol: (x, df, p, d) => `${cap(x)} = ${df}. Dimensiones: ${p} = <b>${d}</b>` },
